import img1 from "../assets/1.jpeg";
import img2 from "../assets/2.jpeg";
import img3 from "../assets/3.jpeg";
import img4 from "../assets/4.jpeg";
import img5 from "../assets/5.jpeg";
import img6 from "../assets/6.jpeg";
import img8 from "../assets/8.jpeg";
import img9 from "../assets/9.jpeg";
import img15 from "../assets/15.jpeg";
import img16 from "../assets/16.jpeg";
import img17 from "../assets/17.jpeg";
import img18 from "../assets/18.jpeg";

const products = [
  // 🧸 Baby Suit Set
  { id: 1, name: "Baby Suit Set 1", price: 999, category: "Suit", age: "0-6 months", image: img1 },
  { id: 2, name: "Baby Suit Set 2", price: 999, category: "Suit", age: "0-6 months", image: img2 },
  { id: 3, name: "Baby Suit Set 3", price: 999, category: "Suit", age: "0-6 months", image: img3 },

  // 🧥 Sweaters
  { id: 16, name: "Sweater 1", price: 799, category: "Sweater", age: "1 year", image: img16 },
  { id: 17, name: "Sweater 2", price: 799, category: "Sweater", age: "1 year", image: img17 },
  { id: 18, name: "Sweater 3", price: 799, category: "Sweater", age: "1 year", image: img18 },

  // 🧢 Caps
  { id: 8, name: "S 1", price: 499, category: "Cap", age: "0-6 months", image: img8 },
  { id: 9, name: "Cap 2", price: 499, category: "Cap", age: "0-6 months", image: img9 },
  { id: 15, name: "Cap 3", price: 499, category: "Cap", age: "0-6 months", image: img15 },

  // 🧦 Socks
  { id: 4, name: "Socks 1", price: 399, category: "Socks", age: "0-6 months", image: img4 },
  { id: 5, name: "Socks 2", price: 399, category: "Socks", age: "0-6 months", image: img5 },
  { id: 6, name: "Socks 3", price: 399, category: "Socks", age: "0-6 months", image: img6 },
];

export default products;
